+        if (isOldCluster()) {
+            assertRestStatus(client().performRequest(createNewIndex("index-old-agg")), RestStatus.OK);
+            assertRestStatus(client().performRequest(indexDocument("index-old-agg", "foofoo", "1024.12.321.777", "1")), RestStatus.CREATED);
