+    private static boolean canMergeModelSettings(
+        SemanticTextField.ModelSettings previous,
+        SemanticTextField.ModelSettings current,
+        Conflicts conflicts
+    ) {
+        if (Objects.equals(previous, current)) {
+            return true;
+        }
+        if (previous == null) {
+            return true;
+        }
+        conflicts.addConflict("model_settings", "");
+        return false;
+    }
