+            if (keys == null) {
+                close();
+            }
+        }
+    }
+
+    public int getKey1(long id) {
+        return keys.get(3 * id);
+    }
+
+    public int getKey2(long id) {
+        return keys.get(3 * id + 1);
+    }
+
+    public int getKey3(long id) {
+        return keys.get(3 * id + 2);
+    }
