+            final long id = id(index);
+            if (id == -1) {
+                return id;
+            } else {
+                long keyOffset = 3 * id;
+                if ((keys.get(keyOffset) == key1 && keys.get(keyOffset + 1) == key2 && keys.get(keyOffset + 2) == key3)) {
