+    private long set(int key1, int key2, int key3, long id) {
+        assert size < maxSize;
+        long index = slot(hash(key1, key2, key3), mask);
+        while (true) {
+            final long curId = id(index);
+            if (curId == -1) { // means unset
+                id(index, id);
+                append(id, key1, key2, key3);
